#include <bits/stdc++.h>
using namespace std;

int n;
long long limitT;
vector<long long> a;

// Simulates `docks` docks: each truck, in order, starts at the earliest free dock.
bool valid(int docks) {
    priority_queue<long long, vector<long long>, greater<long long>> heap(greater<long long>(), vector<long long>(docks, 0));
    long long latest = 0;
    for (long long v : a) {
        long long done = heap.top() + v;
        heap.pop();
        heap.push(done);
        latest = max(latest, done);
    }
    return latest <= limitT;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> limitT;
    a.resize(n);
    for (auto &x : a) cin >> x;
    // Feasibility is monotone in the number of docks.
    int lo = 1, hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (valid(mid)) hi = mid;
        else lo = mid + 1;
    }
    cout << lo << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    // Simulates k docks with a min-heap of free times: each truck, in order, takes the earliest one.
    static boolean valid(long[] a, int k, long t) {
        long[] heap = new long[k];
        for (long v : a) {
            long x = heap[0] + v;
            int i = 0;
            while (true) {
                int c = 2 * i + 1;
                if (c >= k) break;
                if (c + 1 < k && heap[c + 1] < heap[c]) c++;
                if (heap[c] >= x) break;
                heap[i] = heap[c];
                i = c;
            }
            heap[i] = x;
        }
        long latest = 0;
        for (long x : heap) latest = Math.max(latest, x);
        return latest <= t;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long t = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Feasibility is monotone in the number of docks.
        int lo = 1, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (valid(a, mid, t)) hi = mid;
            else lo = mid + 1;
        }
        System.out.println(lo);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

// Simulates k docks with a min-heap of free times: each truck, in order, takes the earliest one.
func valid(a []int64, k int, t int64) bool {
	heap := make([]int64, k)
	for _, v := range a {
		x := heap[0] + v
		i := 0
		for {
			c := 2*i + 1
			if c >= k {
				break
			}
			if c+1 < k && heap[c+1] < heap[c] {
				c++
			}
			if heap[c] >= x {
				break
			}
			heap[i] = heap[c]
			i = c
		}
		heap[i] = x
	}
	return slices.Max(heap) <= t
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	t := nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	// Feasibility is monotone in the number of docks.
	lo, hi := 1, n
	for lo < hi {
		mid := (lo + hi) / 2
		if valid(a, mid, t) {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	fmt.Println(lo)
}
